type F = Record<string, string>;
type Out = { kpis?: [string, React.ReactNode, string?][]; chart?: { title: string; kind: 'bar' | 'hbar' | 'stack' | 'area' | 'line' | 'donut'; data: any[]; keys?: { key: string; label: string; color?: string }[]; money?: boolean }; chart2?: Out['chart']; rows: any[]; cols: Col[]; rec?: string; note?: string };
type Rep = { id: string; title: string; group: string; legacy: string; desc: string; filters: string[]; run: (db: any, f: F) => Out };

const inRange = (d: string, f: F) => (!f.from || (d || '') >= f.from) && (!f.to || (d || '') <= f.to);
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const inMonth = (d: string, f: F) => (!f.month || new Date(d).getMonth() === MON.indexOf(f.month)) && (!f.year || String(new Date(d).getFullYear()) === f.year);
const lrCols = (db: any): Col[] => [{ key: 'lrNo', label: 'LR no.', render: (r) => <DocNo>{r.lrNo}</DocNo>, mobile: 'title' }, { key: 'placeDate', label: 'Date', render: (r) => fmtDate(r.placeDate) }, { key: 'c', label: 'Consignor', value: (r) => lookup.cust(db, r.consignorId)?.short, mobile: 'sub' }, { key: 'route', label: 'Route', value: (r) => `${r.source} → ${r.destination}` }, { key: 'truck', label: 'Truck', value: (r) => lookup.truckNo(db, r.truckId) }, { key: 'freight', label: 'Freight', align: 'right', render: (r) => inr(r.freight), mobile: 'right' }, { key: 'stage', label: 'Stage', value: (r) => lrStage(db, r), render: (r) => <StatusBadge s={lrStage(db, r)} />, mobile: 'meta' }];
function truckPnL(db: any, t: any, f: F) {
  const trips = db.trips.filter((x: any) => x.truckId === t.id && inMonth(x.startDate, f));
  const lrs = db.lrs.filter((l: any) => l.truckId === t.id && l.vehicle === 'Own' && inMonth(l.placeDate, f));
  const exp = db.tripExpenses.filter((e: any) => e.truckId === t.id && inMonth(e.date, f));
  const mon = db.monthlyExpenses.filter((e: any) => e.truckId === t.id && inMonth(e.date, f));
  const jc = db.jobcards.filter((j: any) => j.truckId === t.id && inMonth(j.inDate, f));
  const km = sum(trips.filter((x: any) => x.completed), (x: any) => x.closingKm - x.openingKm);
  const diesel = sum(exp.filter((e: any) => isDiesel(db, e.typeId)), (e: any) => e.qty);
  const revenue = sum(lrs, (l: any) => l.freight);
  const variable = sum(exp, (e: any) => e.amount) + sum(mon, (e: any) => e.amount) + sum(jc, (j: any) => j.net);
  const fixed = Math.round((t.monthlyExp + t.emi) * (f.month ? 1 : 1.5));
  return { trips: trips.length, km, diesel, avg: diesel ? km / diesel : 0, revenue, variable, fixed, profit: revenue - variable - fixed, perKm: km ? (revenue - variable - fixed) / km : 0 };
}
function rakePnL(db: any, s: any) {
  const lrs = db.lrs.filter((l: any) => l.scheduleId === s.id);
  const rev = sum(lrs, (l: any) => l.freight), rail = sum(s.mrrr?.rows || [], (r: any) => r.railFreight), dc = sum(db.dcs.filter((d: any) => d.scheduleId === s.id), (d: any) => d.freight);
  const ham = sum(s.loads, (l: any) => l.labourCharge) + sum(db.grns.filter((g: any) => lrs.some((l: any) => l.id === g.lrId)), (g: any) => g.labourCharge) + sum(db.dgrns.filter((g: any) => g.scheduleId === s.id), (g: any) => g.labourCharge);
  const feeder = sum(db.grns.filter((g: any) => lrs.some((l: any) => l.id === g.lrId)), (g: any) => g.net);
  const dem = (s.dcwcSrc?.amount || 0) - (s.dcwcSrc?.waiver?.amount || 0) + (s.dcwcDst?.amount || 0) + (s.dcwcSrc?.wc?.amount || 0) + (s.dcwcDst?.wc?.amount || 0);
  return { rev, rail, dc, ham, feeder, dem, cost: rail + dc + ham + feeder + dem, profit: rev - rail - dc - ham - feeder - dem, lrs: lrs.length };
}

