const LINKED: Record<string, [string, any?]> = { 'stock-verify': ['wh/verification'], 'stock-move': ['wh/movement'], 'godown-stock': ['wh/stock'], 'godown-stock-summary': ['wh/stock'], 'damage-shortage': ['wh/damage'], 'quality-control': ['wh/qc'], 'client-outstanding': ['fin/receivables'], ledger: ['fin/ledger'], 'rate-matrix': ['cust/rate-contracts'] };

